<style>
.growth-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.growth-grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.growth-stat{padding:1rem;border:1px solid var(--border);border-radius:var(--radius,12px);background:var(--surface)}.growth-stat small{display:block;color:var(--text-muted);margin-bottom:.35rem}.growth-stat strong{font-size:1.25rem}.growth-toolbar{display:flex;gap:.75rem;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:1rem}.growth-filters{display:flex;gap:.6rem;flex-wrap:wrap;align-items:end}.growth-chip{display:inline-flex;align-items:center;gap:.35rem;padding:.28rem .65rem;border-radius:999px;border:1px solid var(--border);font-size:.75rem}.growth-timeline{display:grid;gap:.75rem}.growth-timeline-item{padding:.9rem;border-right:3px solid var(--gold);background:var(--surface);border-radius:10px}.growth-timeline-item small{color:var(--text-muted)}.growth-section{margin-top:1rem}.growth-note{padding:.85rem 1rem;border:1px dashed var(--border);border-radius:10px;color:var(--text-muted);background:color-mix(in srgb,var(--surface) 92%,var(--gold) 8%)}.growth-actions{display:flex;gap:.5rem;flex-wrap:wrap}.growth-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.8rem}.delivery-status{font-weight:700}.delivery-history{display:grid;gap:.6rem}.delivery-history>div{padding:.7rem;border:1px solid var(--border);border-radius:8px}.loyalty-positive{color:var(--success,#16845b)}.loyalty-negative{color:var(--danger,#b42318)}
@media(max-width:1000px){.growth-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.growth-form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.growth-grid,.growth-grid-2,.growth-form-grid{grid-template-columns:1fr}}
</style>